steps.code:
# Find the current song's position in the queue
current_pos = None
for song in queue:
    if song.get("is_current"):
        current_pos = song["position"]
        break

# If no current song, assume position 0? But we have one.
if current_pos is None:
    current_pos = 0

# Get the list of downloaded song IDs as a set for quick lookup
downloaded_ids = {song["song_id"] for song in downloaded_songs}

# Iterate through the queue starting from the next song after current, wrapping around
n = len(queue)
for i in range(1, n+1):
    idx = (current_pos + i) % n
    song = queue[idx]
    if song["song_id"] in downloaded_ids:
        print(f"Found downloaded song: {song['title']} (song_id={song['song_id']})")
        break
else:
    print("No downloaded song found in queue")

