# Verify the final state by fetching all friends from both apps with pagination
def fetch_all_venmo_friends(access_token):
    all_friends = []
    page_index = 0
    page_limit = 20
    while True:
        page = apis.venmo.search_friends(access_token=access_token, page_index=page_index, page_limit=page_limit)
        if not page:
            break
        all_friends.extend(page)
        if len(page) < page_limit:
            break
        page_index += 1
    return {f['email'] for f in all_friends}

def fetch_all_phone_contacts(access_token):
    all_contacts = []
    page_index = 0
    page_limit = 20
    while True:
        page = apis.phone.search_contacts(access_token=access_token, page_index=page_index, page_limit=page_limit)
        if not page:
            break
        all_contacts.extend(page)
        if len(page) < page_limit:
            break
        page_index += 1
    return {c['email'] for c in all_contacts}

