steps.code:
# Let's find song IDs for each archive song by searching
archive_song_ids = {}
for title, artist in archive_songs:
    # Search by title
    results = apis.spotify.search_songs(query=title, access_token=spotify_login['access_token'], page_limit=20)
    found = None
    for song in results:
        if song['title'].lower() == title.lower():
            # Check if artist matches
            for art in song['artists']:
                if art['name'].lower() == artist.lower():
                    found = song['song_id']
                    break
            if found:
                break
    if found is None:
        # Try searching with title + artist
        results2 = apis.spotify.search_songs(query=f"{title} {artist}", access_token=spotify_login['access_token'], page_limit=20)
        for song in results2:
            if song['title'].lower() == title.lower():
                for art in song['artists']:
                    if art['name'].lower() == artist.lower():
                        found = song['song_id']
                        break
                if found:
                    break
    if found is None:
        print(f"NOT FOUND: {title} by {artist}")
    else:
        archive_song_ids[(title, artist)] = found
        print(f"Found: {title} by {artist} -> {found}")

print(f"Total found: {len(archive_song_ids)}")

