steps.code:
# Let's find the song IDs for all old songs by searching and matching title + artists.
old_song_ids = []
for song in old_songs:
    title = song['title']
    artists = set(song['artists'])
    # Search for the song
    results = apis.spotify.search_songs(query=title, access_token=spotify_login['access_token'], page_limit=20)
    found = None
    for r in results:
        if r['title'].strip().lower() == title.lower():
            result_artists = {a['name'] for a in r['artists']}
            if result_artists == artists:
                found = r['song_id']
                break
    if found is not None:
        old_song_ids.append(found)
        print(f"Found: {title} -> song_id {found}")
    else:
        print(f"NOT FOUND: {title}")

print("Old song IDs:", old_song_ids)

