# We have all 13 song IDs. Now let's remove them from all playlists and add to the new playlist.
# First, define the target song IDs
target_song_ids = {295, 324, 22, 245, 320, 92, 299, 4, 278, 69, 219, 298, 265}

# Iterate over each playlist and remove any target songs
for playlist in playlists:
    pid = playlist['playlist_id']
    for song_id in playlist['song_ids']:
        if song_id in target_song_ids:
            print(f"Removing song {song_id} from playlist {pid}")
            result = apis.spotify.remove_song_from_playlist(playlist_id=pid, song_id=song_id, access_token=spotify_token)
            print(result)

