steps.code:
# Get release dates for all liked songs
release_dates = {}
for song in all_liked_songs:
    song_id = song['song_id']
    details = apis.spotify.show_song(song_id=song_id)
    if isinstance(details, dict) and 'release_date' in details:
        release_dates[song_id] = details['release_date']
    else:
        print("Error for song", song_id, details)
print("Release dates fetched:", len(release_dates))

