# Build new content by replacing TODO with release month/year
import re
from datetime import datetime

# Parse release dates into month/year format
release_month_year = {}
for title, date_str in release_dates.items():
    dt = datetime.fromisoformat(date_str)
    release_month_year[title] = f"{dt.month:02d}/{dt.year}"

# Split note content into lines
lines = note['content'].split('\n')
new_lines = []
for line in lines:
    if 'RELEASED_AT TODO' in line:
        # Extract song title: pattern "- <title> BY <artists> RELEASED_AT TODO"
        # Use regex to get title
        m = re.match(r'^- (.+?) BY .+ RELEASED_AT TODO$', line)
        if m:
            title = m.group(1)
            if title in release_month_year:
                new_line = line.replace('RELEASED_AT TODO', f"RELEASED_AT {release_month_year[title]}")
                new_lines.append(new_line)
            else:
                # If not found, keep as is (shouldn't happen)
                new_lines.append(line)
        else:
            new_lines.append(line)
    else:
        new_lines.append(line)

new_content = '\n'.join(new_lines)
print(new_content)

# Print all liked songs to see their details
for song in all_liked:
