# Parse the note content to extract songs with TODO
import re

content = note['content']
lines = content.split('\n')
todo_songs = []
for line in lines:
    line = line.strip()
    if line.startswith('- '):
        # Remove leading "- "
        item = line[2:]
        # Split on " RELEASED_AT "
        if ' RELEASED_AT ' in item:
            song_part, released = item.split(' RELEASED_AT ', 1)
            if released.strip() == 'TODO':
                # Split song_part on " BY "
                if ' BY ' in song_part:
                    title, artists_str = song_part.split(' BY ', 1)
                    artists = [a.strip() for a in artists_str.split(',')]
                    todo_songs.append({'title': title.strip(), 'artists': artists, 'line': line})
                else:
                    print(f"Malformed line: {line}")
            else:
                # Already has date, skip
                pass
        else:
            print(f"No RELEASED_AT in line: {line}")

print(f"Found {len(todo_songs)} songs with TODO")
for s in todo_songs:
    print(s)

