# Get all liked songs (paginate)
liked_songs = []
page = 0
while True:
    result = apis.spotify.show_liked_songs(access_token=access_token, page_index=page, page_limit=20)
    if not result:
        break
    liked_songs.extend(result)
    if len(result) < 20:
        break
    page += 1

liked_song_ids = {song['song_id'] for song in liked_songs}
print(f"Liked song IDs: {liked_song_ids}")

# Remove songs from queue in descending order to avoid position shifts
for pos in sorted(positions_to_remove, reverse=True):
    print(apis.spotify.remove_song_from_queue(position=pos, access_token=access_token))

